{
  "summary": "Jeep Cherokee ADAS automatic emergency braking: recurring TCM programming loss with neutral lock, battery power surges, loss of emergency braking/4x4/5th gear, and engine-transmission communication loss while driving.",
  "group": "adas",
  "symptoms": [
    "transmission control module loses programming repeatedly",
    "locks into neutral while driving",
    "battery power surges",
    "loss of emergency braking system",
    "cannot apply emergency brake",
    "loss of 4x4 modes including snow sport and four-wheel drive low",
    "full drive cannot be engaged",
    "will not shift in or out of 5th gear",
    "starts in 5th gear",
    "no towing power",
    "complete shutdown while driving",
    "loss of communication among vehicle modules and between engine and transmission",
    "driving nearly impossible"
  ],
  "conditions": [
    "after service",
    "intermittent"
  ],
  "fault_codes": [],
  "safety_relevant": true,
  "missing_info": [
    "mileage",
    "date"
  ],
  "clues": [
    {
      "kind": "component_group",
      "quote": "emergency braking system"
    },
    {
      "kind": "symptom",
      "quote": "transmission control module had lost its programming"
    },
    {
      "kind": "symptom",
      "quote": "not holding on to its programming"
    },
    {
      "kind": "symptom",
      "quote": "It locks itself into neutral when we are driving"
    },
    {
      "kind": "symptom",
      "quote": "surges of power with the battery"
    },
    {
      "kind": "symptom",
      "quote": "no longer has any emergency braking system"
    },
    {
      "kind": "symptom",
      "quote": "We cannot put the emergency brake on in fact."
    },
    {
      "kind": "symptom",
      "quote": "We lost all of our 4x4 variations such as snow sport and four wheel drive low."
    },
    {
      "kind": "symptom",
      "quote": "Full drive is no longer able to be engaged at all with the transmission."
    },
    {
      "kind": "symptom",
      "quote": "It will not shift in or out of 5th gear"
    },
    {
      "kind": "symptom",
      "quote": "starting out in 5th gear"
    },
    {
      "kind": "symptom",
      "quote": "no towing power whatsoever right now"
    },
    {
      "kind": "symptom",
      "quote": "It has shut off completely in the middle of us driving bfore."
    },
    {
      "kind": "symptom",
      "quote": "lose it's communication with all of the other modules in the vehicle"
    },
    {
      "kind": "symptom",
      "quote": "engine itself is no longer communicating with the transmission"
    },
    {
      "kind": "symptom",
      "quote": "makes driving the vehicle almost impossible."
    },
    {
      "kind": "condition",
      "quote": "We took it to a dealership"
    },
    {
      "kind": "condition",
      "quote": "Less than a year later we are back with the same issues again"
    },
    {
      "kind": "condition",
      "quote": "when we are driving"
    },
    {
      "kind": "condition",
      "quote": "in the middle of us driving"
    },
    {
      "kind": "safety",
      "quote": "It locks itself into neutral when we are driving"
    },
    {
      "kind": "safety",
      "quote": "It has shut off completely in the middle of us driving bfore."
    },
    {
      "kind": "safety",
      "quote": "no longer has any emergency braking system"
    }
  ]
}

